package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UserinfoSignedResponseAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property userinfo signed response alg of oauth client ")
  void test_userinfo_signed_response_alg_v_o_builder() {
    Assertions.assertFalse(
        UserinfoSignedResponseAlgVO.nullValue().getUserinfoSignedResponseAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        UserinfoSignedResponseAlgVO.tryFrom(null).getUserinfoSignedResponseAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        UserinfoSignedResponseAlgVO.from("one").getUserinfoSignedResponseAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> UserinfoSignedResponseAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", UserinfoSignedResponseAlgVO.from("one").toString());
  }
}
